"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["13314"],{96252(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.regra_de_comprovacao.consequencia_incoerente_com_acao_da_vaga","status":422,"titulo":"A consequ\xeancia n\xe3o corresponde \xe0 a\xe7\xe3o de indeferimento da modalidade alcan\xe7ada"},"descricao":{"codigo":"uniplus.selecao.regra_de_comprovacao.consequencia_incoerente_com_acao_da_vaga","requisitos":["UNI-REQ-0070"],"oQueAconteceu":["Um grupo com quantidade m\xednima de itens pode ter consequ\xeancia pr\xf3pria de indeferimento. Quando uma\\nmodalidade de vaga declara o que acontece com o candidato indeferido (a a\xe7\xe3o de indeferimento),\\na consequ\xeancia do grupo tem de ser a mesma. O grupo apontado declara uma consequ\xeancia\\ndiferente da a\xe7\xe3o de uma modalidade que ele pode alcan\xe7ar.","O grupo alcan\xe7a as modalidades que qualquer um dos documentos dele pode alcan\xe7ar pelas\\ncondi\xe7\xf5es. S\xf3 entram na compara\xe7\xe3o as modalidades que declaram a\xe7\xe3o de indeferimento. A consequ\xeancia\\ndo grupo e a a\xe7\xe3o da modalidade usam o mesmo c\xf3digo (`RETIRA_A_MODALIDADE`). A consequ\xeancia `RETIRA_O_ACRESCIMO` n\xe3o entra nesta compara\xe7\xe3o: ela retira s\xf3 o acr\xe9scimo, n\xe3o decide o destino da modalidade e pode ser declarada em qualquer grupo. A mensagem de detalhe indica o grupo e a modalidade\\nem conflito.","A confer\xeancia acontece quando a configura\xe7\xe3o vai ser congelada, na publica\xe7\xe3o ou na retifica\xe7\xe3o em ato \xfanico. Ela vem depois da dos documentos\\nexigidos (ver\\n[`documento_exigido.consequencia_incoerente_com_acao_da_vaga`](/erros/uniplus.selecao.documento_exigido.consequencia_incoerente_com_acao_da_vaga)),\\ne a confer\xeancia re\xfane todas as viola\xe7\xf5es encontradas, sem parar na primeira."],"comoResolver":["Alinhe a consequ\xeancia do grupo \xe0 a\xe7\xe3o de indeferimento da modalidade apontada, ou revise a\\na\xe7\xe3o dessa modalidade, se for ela que est\xe1 errada. Depois, repita a opera\xe7\xe3o."],"ondeAparece":["Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Regra de comprovacao"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"0258f07cac6c9b7f9d70290a4b0385549eb99572"}}')}}]);